Method.Source:
/// <summary>
/// MPJ-5904, GVivanco, 26Jun2021
/// Finds a NumberSequenceReference for the METALMSupplierVolumetricRebateNumber
/// EDT
/// </summary>
/// <returns>A METALMSupplierVolumetricRebateNumber NumberSequenceReference
/// if found, otherwise null</returns>
static NumberSequenceReference METnumRefALMSupplierVolumetricRebateNumber()
{
    return NumberSeqReference::findReference(extendedTypeNum(METALMSupplierVolumetricRebateNumber));
}

/// <summary>
/// Finds a NumberSequenceReference for the METCBCTNumber (Chargeback chargethrough number)
/// </summary>
/// <returns>A METCBCTNumber NumberSequenceReference
/// if found, otherwise null</returns>
static NumberSequenceReference METnumRefCBCTNumber()
{
    return NumberSeqReference::findReference(extendedTypeNum(METCBCTNumber));
}

/// <summary>
/// Number sequence for NAT 30 number
/// </summary>
